-- CreditMe/Lisa PostgreSQL schema generated from the fixed-width dossier dictionary.
-- Source: Sopra Banking Software 22-JAN-2021, Dossier, 49 pages.
-- Catalog rows preserve positions/pictures; no undocumented relationships are inferred.

BEGIN;
CREATE SCHEMA IF NOT EXISTS creditme;

CREATE TABLE IF NOT EXISTS creditme.record_definition (
    record_code text PRIMARY KEY,
    record_number integer,
    label text NOT NULL,
    source_line integer NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS creditme.field_definition (
    record_code text NOT NULL REFERENCES creditme.record_definition(record_code) ON DELETE CASCADE,
    ordinal integer NOT NULL,
    start_position integer NOT NULL CHECK (start_position > 0),
    end_position integer NOT NULL CHECK (end_position >= start_position),
    field_length integer NOT NULL CHECK (field_length = end_position - start_position + 1),
    level smallint NOT NULL CHECK (level > 0),
    field_name text NOT NULL,
    picture text NOT NULL,
    usage text NOT NULL,
    data_type text NOT NULL CHECK (data_type IN ('text', 'numeric')),
    description text NOT NULL DEFAULT '',
    source_line integer NOT NULL,
    PRIMARY KEY (record_code, start_position, end_position, field_name, picture)
);

CREATE INDEX IF NOT EXISTS field_definition_name_idx
    ON creditme.field_definition (field_name);

CREATE TABLE IF NOT EXISTS creditme.raw_record_payload (
    payload_id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    record_code text NOT NULL REFERENCES creditme.record_definition(record_code),
    record_key text,
    payload text NOT NULL,
    source_file text,
    received_at timestamptz NOT NULL DEFAULT now(),
    CHECK (length(payload) > 0)
);

CREATE INDEX IF NOT EXISTS raw_record_payload_record_idx
    ON creditme.raw_record_payload (record_code, record_key);
CREATE UNIQUE INDEX IF NOT EXISTS raw_record_payload_record_key_uq
    ON creditme.raw_record_payload (record_code, record_key)
    WHERE record_key IS NOT NULL;

CREATE TABLE IF NOT EXISTS creditme.dossier (
    dossier_key text PRIMARY KEY,
    source_payload_id bigint REFERENCES creditme.raw_record_payload(payload_id),
    product_code text,
    currency_code char(3),
    nominal_amount numeric(18,2) CHECK (nominal_amount IS NULL OR nominal_amount >= 0),
    duration_months integer CHECK (duration_months IS NULL OR duration_months > 0),
    proposal_date date,
    created_at timestamptz NOT NULL DEFAULT now(),
    CHECK (currency_code IS NULL OR currency_code = upper(currency_code))
);

COMMENT ON TABLE creditme.field_definition IS
    'Exhaustive field catalog extracted from the fixed-width dictionary; positions are 1-based.';
COMMENT ON TABLE creditme.raw_record_payload IS
    'Staging table for payloads whose business relationships are not documented by the source.';
COMMENT ON TABLE creditme.dossier IS
    'Hackathon projection of explicitly identifiable ENR-DLANC fields; not a claim of undocumented relationships.';



COMMIT;
